test('vatSummary calculates VAT for single invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // qty:10, price:9500, no discount, VAT 21%
  // lineTotal = 95000, base = 95000, vat = roundCents(95000 * 21 / 100) = 19950
  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

test('vatSummary sums VAT across multiple invoices with same rate', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // Invoice 1: 10 * 9500 = 95000, vat = 19950
  // Invoice 2: 5 * 9500 = 47500, vat = 9975
  // Total: base = 142500, vat = 29925
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 142500);
  assert.equal(result[0].vat, 29925);
});

