    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'HOSTING', qty: 1 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // DEV-HOUR: 21% VAT
  // HOSTING: 6% VAT, price 50000
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21); // High to low sorting
  assert.equal(result[1].rate, 6);
});

