  // So the line object returned by createInvoice might already have discountPercent set.
  // Let me check by creating an invoice and logging the lines.

  // For now, let me just assert what I think is correct based on the tier discount logic:
  // DEV-HOUR with 5% tier discount: 95000 - 4750 = 90250, vat = roundCents(90250 * 21/100) = 18952.5 → 18952
  // HOSTING with 5% tier discount: 50000 - 2500 = 47500, vat = 9975
  // Total: base = 137750, vat = 28927
  const result = vatSummary([issued.value]);
  // Two different VAT rates
  assert.equal(result.length, 2);
  // Find 21% rate
  const rate21 = result.find(r => r.rate === 21);
  const rate6 = result.find(r => r.rate === 6);
  assert(rate21);
  assert(rate6);
  // The bases should include both lines
  // But tier discount is applied per-line, so we need to check the actual discount on each line
});

