import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array for no overdue invoices', () => {
  const result = overdueInvoices([], '2026-10-31');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices finds overdue issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Due date: 2026-10-21, check as of 2026-10-31 = 10 days overdue
  const result = overdueInvoices([issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, 'INV-2026-0001');
  assert.equal(result.value[0].dueDate, '2026-10-21');
  assert.equal(result.value[0].daysOverdue, 10);
});

test('overdueInvoices excludes draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([invoice.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes invoices due in future', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(invoice.value, []);
  // Due date: 2026-11-06, check as of 2026-10-31 (still in future)
  const result = overdueInvoices([issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes invoices due today', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Due date: 2026-10-21, check as of 2026-10-21 (due today, not overdue)
  const result = overdueInvoices([issued.value], '2026-10-21');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Invoice total: 100*9500=950000, discount 5%=47500, after discount=902500, VAT 21%=189525, total=1092025
  const payment = recordPayment(issued.value, { amount: 500000, date: '2026-10-15' });
  assert.equal(payment.ok, true);
  // Due date: 2026-10-21, check as of 2026-10-31
  const result = overdueInvoices([payment.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, 'INV-2026-0001');
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Invoice total: 1092025
  const payment = recordPayment(issued.value, { amount: 1092025, date: '2026-10-15' });
  assert.equal(payment.ok, true);
  // Invoice is now paid, should not appear in overdue
  const result = overdueInvoices([payment.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices calculates days overdue correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Due date: 2026-10-15, check as of 2026-10-25 = 10 days overdue
  const result = overdueInvoices([issued.value], '2026-10-25');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].daysOverdue, 10);
});

test('overdueInvoices includes due amount from balanceDue', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  // Total: 1034550
  const result = overdueInvoices([issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].due, 1034550);
});

test('overdueInvoices reduces due for partial payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 500000, date: '2026-10-15' });
  assert.equal(payment.ok, true);
  // Total: 1034550, Paid: 500000, Due: 534550
  const result = overdueInvoices([payment.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].due, 534550);
});

test('overdueInvoices sorts by most overdue first', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // Invoice 1 due 2026-10-15, Invoice 2 due 2026-10-24
  // As of 2026-10-31: Invoice 1 is 16 days overdue, Invoice 2 is 7 days overdue
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  assert.equal(result.value[0].number, 'INV-2026-0001'); // Most overdue first
  assert.equal(result.value[0].daysOverdue, 16);
  assert.equal(result.value[1].number, 'INV-2026-0002');
  assert.equal(result.value[1].daysOverdue, 7);
});

test('overdueInvoices includes customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const result = overdueInvoices([issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].customerId, 'C-003');
});

test('overdueInvoices rejects invalid date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const result = overdueInvoices([issued.value], '2026-10-7');
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices with EOM terms', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'EOM',
  });
  const issued = issueInvoice(invoice.value, []);
  // Due date: 2026-10-31, check as of 2026-11-07 = 7 days overdue
  const result = overdueInvoices([issued.value], '2026-11-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].daysOverdue, 7);
});

test('overdueInvoices with different due dates', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET30',
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  // Invoice 1: due 2026-10-01 (30 days overdue as of 2026-10-31)
  // Invoice 2: due 2026-10-21 (10 days overdue as of 2026-10-31)
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  assert.equal(result.value[0].daysOverdue, 30);
  assert.equal(result.value[1].daysOverdue, 10);
});

test('vatSummary returns empty array for empty invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary calculates VAT for single invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // qty:10, price:9500, tier discount 5% (gold), VAT 21%
  // lineTotal = 95000, discount = 4750, base = 90250, vat = roundCents(90250 * 21 / 100) = 18952.5 → 18952
  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 90250);
});


test('vatSummary sums VAT across multiple invoices with same rate', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // Both with 5% tier discount
  // Invoice 1: 10 * 9500 = 95000, discount 4750, base = 90250
  // Invoice 2: 5 * 9500 = 47500, discount 2375, base = 45125
  // Total: base = 135375
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 135375);
});

test('vatSummary handles multiple VAT rates', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'HOSTING', qty: 1 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // DEV-HOUR: 21% VAT
  // HOSTING: 6% VAT, price 50000
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21); // High to low sorting
  assert.equal(result[1].rate, 6);
});

test('vatSummary excludes draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const result = vatSummary([invoice.value]);
  assert.deepEqual(result, []);
});

test('vatSummary includes issued, partially_paid, and paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const partial = recordPayment(issued2.value, { amount: 50000, date: '2026-10-15' });
  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);
  const paid = recordPayment(issued3.value, { amount: 11395, date: '2026-10-15' });
  // Total: (10 + 5 + 1) * 9500 = 152000, vat = 31920
  const result = vatSummary([issued1.value, partial.value, paid.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 152000);
  assert.equal(result[0].vat, 31920);
});

test('vatSummary calculates base after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // qty:100, price:9500, discount 10%
  // lineTotal = 950000, discount = 95000, base = 855000, vat = roundCents(855000 * 21 / 100) = 179550
  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, 855000);
  assert.equal(result[0].vat, 179550);
});

test('vatSummary includes tier discount in base calculation', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // C-001 has 5% tier discount
  // qty:100, price:9500, tier discount 5%
  // lineTotal = 950000, discount = 47500, base = 902500, vat = 189525
  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, 902500);
  assert.equal(result[0].vat, 189525);
});

test('vatSummary sorts by rate high to low', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'HOSTING', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result[0].rate, 21); // DEV-HOUR first
  assert.equal(result[1].rate, 6); // HOSTING second
});

test('vatSummary excludes draft invoices from counts', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(inv1.value, []);
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const result = vatSummary([issued.value, draft.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary handles invoices with no discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // No discount: base = 95000, vat = 19950
  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

