    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const partial = recordPayment(issued2.value, { amount: 50000, date: '2026-10-15' });
  // Both invoices included: total base = 90250 + 45125 = 135375
  const result = vatSummary([issued1.value, partial.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 135375);
