    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result[0].rate, 21); // DEV-HOUR first
  assert.equal(result[1].rate, 6); // HOSTING second
});

test('vatSummary excludes draft invoices from counts', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(inv1.value, []);
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const result = vatSummary([issued.value, draft.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary handles invoices with no discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // No discount: base = 95000, vat = 19950
  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

